    'ফোনে যে মুদ্রায় রেট ঠিক হয়েছিল — অঙ্কগুলো ইনভয়েসে যেমন আছে ঠিক তেমন লিখুন। রেকর্ড করার সময় কার্যকর হারে বিল রুপিতে রূপান্তরিত হয়, এবং ক্লায়েন্ট যেভাবেই হোক রুপিতে চার্জ হন।',
